questionvariables.text:
/* Original rectangle dimensions, cm */
w : rand(6) + 3;
h : rand(6) + 3;

/* Linear scale factor p/q in lowest terms, p > q so the photo is enlarged */
qden : rand(3) + 2;
pnum : qden + rand(3) + 1;
g : gcd(pnum, qden);
pnum : pnum / g;
qden : qden / g;

/* Area of the original photograph */
area1 : w * h;

/* Correct area of the enlarged photograph */
ta : decimalplaces(area1 * (pnum/qden)^2, 2);

/* mistakes */
/* Forgot to square the scale factor before scaling the area */
ta1 : decimalplaces(area1 * (pnum/qden), 2);
/* Reversed the scale factor, dividing instead of multiplying */
ta2 : decimalplaces(area1 / (pnum/qden)^2, 2);
